fixtures.ci/pane_wait.py:
"""Helpers for driving the standing build pane from CI automation."""

import subprocess

PANE = "release"


def _panectl(*args):
    return subprocess.run(
        ["panectl", *args], capture_output=True, text=True
    )


def send(command):
    """Type `command` into the build pane."""
    _panectl("send", PANE, command)


def wait_for(pattern, timeout=600):
    """Block until `pattern` shows up in the build pane."""
    result = _panectl(
        "await", PANE, "--pattern", pattern, "--timeout", str(timeout)
    )
    return result.returncode == 0


def run_build(version):
    send("make bundle VERSION=%s" % version)
    return wait_for(r"BUNDLE (OK|FAILED)")

